    original_name text NOT NULL,
    path text NOT NULL,
    size_bytes bigint NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE public.file_metadata ADD COLUMN IF NOT EXISTS id uuid;
ALTER TABLE public.file_metadata ADD COLUMN IF NOT EXISTS job_id uuid;
ALTER TABLE public.file_metadata ADD COLUMN IF NOT EXISTS kind text;
ALTER TABLE public.file_metadata ADD COLUMN IF NOT EXISTS original_name text;
ALTER TABLE public.file_metadata ADD COLUMN IF NOT EXISTS path text;
ALTER TABLE public.file_metadata ADD COLUMN IF NOT EXISTS size_bytes bigint;
ALTER TABLE public.file_metadata ADD COLUMN IF NOT EXISTS created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP;

