ALTER TABLE public.processing_jobs ADD COLUMN IF NOT EXISTS id uuid;
ALTER TABLE public.processing_jobs ADD COLUMN IF NOT EXISTS user_id uuid;
ALTER TABLE public.processing_jobs ADD COLUMN IF NOT EXISTS tool_type text;
